01-kas-yra-dokumentas:
/* 01-kas-yra-dokumentas — apibrezimas; žymos 1.2 / 5.5 / 8.8 s; 14 s (koncepcijos.js) */
.k-title { animation: k01T 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.15s both; }
@keyframes k01T { from { opacity: 0; transform: translateY(24px) scale(.98); } to { opacity: 1; transform: none; } }
@keyframes k01r0 { from { opacity: 0; transform: translateY(26px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k01r1 { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k01r2 { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k01h2 { 0%, 42.43% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } 44.64%, 60.71% { box-shadow: 0 0 0 5px rgba(51,99,171,.30); } 62.86%, 100% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } }
@keyframes k01r3 { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k01h3 { 0%, 46.36% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } 48.57%, 60.71% { box-shadow: 0 0 0 5px rgba(51,99,171,.30); } 62.86%, 100% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } }
@keyframes k01r4 { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k01h4 { 0%, 66.00% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } 68.21%, 90.71% { box-shadow: 0 0 0 5px rgba(51,99,171,.30); } 92.86%, 100% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } }
@keyframes k01r5 { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k01h5 { 0%, 69.93% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } 72.14%, 90.71% { box-shadow: 0 0 0 5px rgba(51,99,171,.30); } 92.86%, 100% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } }
.b-term { animation: k01r0 0.7s cubic-bezier(0.16, 1, 0.3, 1) 1.3s both; }
.b-alt_terms { animation: k01r1 0.45s cubic-bezier(0.16, 1, 0.3, 1) 1.85s both; }
.b-item_1 { animation: k01r2 0.45s cubic-bezier(0.16, 1, 0.3, 1) 5.6s both, k01h2 14s linear 0s both; }
.b-item_2 { animation: k01r3 0.45s cubic-bezier(0.16, 1, 0.3, 1) 6.15s both, k01h3 14s linear 0s both; }
.b-item_3 { animation: k01r4 0.45s cubic-bezier(0.16, 1, 0.3, 1) 8.9s both, k01h4 14s linear 0s both; }
.b-item_4 { animation: k01r5 0.45s cubic-bezier(0.16, 1, 0.3, 1) 9.45s both, k01h5 14s linear 0s both; }

02-kas-nera-dokumentas:
/* 02-kas-nera-dokumentas — palyginimas; žymos 1.2 / 6.1 / 10.5 s; 16 s (koncepcijos.js) */
.k-title { animation: k02T 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.15s both; }
@keyframes k02T { from { opacity: 0; transform: translateY(24px) scale(.98); } to { opacity: 1; transform: none; } }
@keyframes k02r0 { from { opacity: 0; transform: translateY(20px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k02h0 { 0%, 10.25% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } 12.19%, 36.25% { box-shadow: 0 0 0 5px rgba(51,99,171,.30); } 38.13%, 100% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } }
@keyframes k02r1 { from { opacity: 0; transform: translateY(20px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes k02h1 { 0%, 40.88% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } 42.81%, 63.75% { box-shadow: 0 0 0 5px rgba(51,99,171,.30); } 65.63%, 100% { box-shadow: 0 0 0 0 rgba(51,99,171,0); } }
@keyframes k02r2 { from { opacity: 0; transform: translateY(20px) scale(.985); } to { opacity: 1; transform: none; } }
.b-old { animation: k02r0 0.55s cubic-bezier(0.16, 1, 0.3, 1) 1.3s both, k02h0 16s linear 0s both; }
.b-arrow { animation: k02r1 0.55s cubic-bezier(0.16, 1, 0.3, 1) 6.2s both; }
.b-new { animation: k02r1 0.55s cubic-bezier(0.16, 1, 0.3, 1) 6.2s both, k02h1 16s linear 0s both; }
